def count_pairs_with_sum(xs: list[int], t: int) -> int:
    # Create a dictionary to store the frequency of each element in xs
    freq = {}
    for x in xs:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1

    count = 0
    # Iterate through the dictionary to find pairs with sum equal to t
    for x in freq:
        complement = t - x
        if complement in freq:
            # If the complement exists, add the number of times the current element appears to the count
            count += freq[x] * freq[complement]

    return count
```

