def gcd_bounded(a: int, b: int) -> int:
    # Ensure a is always less than or equal to b
    if a > b:
        a, b = b, a

    # If a is 1, the GCD is b
    if a == 1:
        return b

    # Iterate from b down to 2 to find the first common divisor
    for i in range(b, 1, -1):
        if a % i == 0 and b % i == 0:
            return i

# Example usage
print(gcd_bounded(48, 60))  # Output: 12
